package store
import("context";"path/filepath";"testing";"time")
func TestTemporaryPasswordState(t *testing.T){ctx:=context.Background();s,_:=Open(filepath.Join(t.TempDir(),"t.db"));defer s.Close();if e:=s.Migrate(ctx);e!=nil{t.Fatal(e)};if e:=s.CreateUser(ctx,"u","old","user","");e!=nil{t.Fatal(e)};exp:=time.Now().Add(30*time.Minute);if e:=s.SetTemporaryPassword(ctx,"u","temp",exp);e!=nil{t.Fatal(e)};u,e:=s.UserByName(ctx,"u");if e!=nil{t.Fatal(e)};if !u.MustChangePassword||u.TempPasswordExpires==0||u.PasswordHash!="temp"{t.Fatal("temporary password state invalid")};if e=s.ChangePassword(ctx,u.ID,"new");e!=nil{t.Fatal(e)};u,_=s.UserByName(ctx,"u");if u.MustChangePassword||u.TempPasswordExpires!=0||u.PasswordHash!="new"{t.Fatal("password change state invalid")}}
func TestAdminCannotUseNormalReset(t *testing.T){ctx:=context.Background();s,_:=Open(filepath.Join(t.TempDir(),"t.db"));defer s.Close();_ = s.Migrate(ctx);_ = s.CreateUser(ctx,"admin","x","portal_admin","secret");if e:=s.SetTemporaryPassword(ctx,"admin","temp",time.Now().Add(time.Minute));e==nil{t.Fatal("portal admin reset should require break-glass")}}
